CREATE TABLE evaluation_audit(id BIGINT NOT NULL AUTO_INCREMENT,request_id VARCHAR(80) NOT NULL,decision VARCHAR(30) NOT NULL,score DOUBLE NOT NULL,pass_rate DOUBLE NOT NULL,summary VARCHAR(500) NOT NULL,created_by VARCHAR(80) NOT NULL,created_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_eval_request UNIQUE(request_id));CREATE INDEX idx_eval_created ON evaluation_audit(created_at);
